#!/bin/bash
# ThreadLab -> wasm64, the way tools/build-app.sh builds a LeanUI app, in two variants:
#   build-wasm.sh mt   the fork's threaded runtime (MULTI_THREAD=ON, -pthread, shared memory)
#   build-wasm.sh st   LeanUI's runtime (MULTI_THREAD=OFF, LEAN_WASM_THREADS=OFF: no -pthread)
# Env: MALLOC=dlmalloc|mimalloc|emmalloc (default dlmalloc, as LeanUI), POOL=<pthread pool size> (mt, default 4)
# Needs: ../build/rt-<v> (fork runtime + libuv built with emcmake), ../build/stdlib-c (C of Init and
# Std.Sync.{Basic,Mutex} generated by the native Lean 4.34.0 `lean -c`), emsdk 6.0.5.
set -euo pipefail
V="${1:?mt or st}"
HERE="$(cd "$(dirname "$0")" && pwd)"; R="$HERE/.."
source "$R/ext/emsdk/emsdk_env.sh" >/dev/null 2>&1
RT="$R/build/rt-$V"; OUT="$HERE/wasm-$V${MALLOC:+-$MALLOC}${POOL:+-pool$POOL}"; OBJ="$R/build/obj-$V"
CG="-O3 -m64 -fwasm-exceptions -sWASM_LEGACY_EXCEPTIONS=1 -D LEAN_EMSCRIPTEN"
[ "$V" = mt ] && CG="$CG -pthread"
INC="-I $RT/include"
mkdir -p "$OBJ" "$OUT"
# Init + Std closure -> one archive (cached per variant)
if [ ! -f "$OBJ/libInit.a" ]; then
  ( cd "$R/build/stdlib-c" && find . -name '*.c' | sort ) > "$OBJ/list.txt"
  export CG INC OBJ R
  cat "$OBJ/list.txt" | xargs -P 4 -I{} bash -c 'f={}; o="$OBJ/$(echo ${f#./} | tr / _ ).o"; [ -f "$o" ] || emcc $CG $INC -c "$R/build/stdlib-c/$f" -o "$o"'
  rm -f "$OBJ/libInit.a"; emar rcs "$OBJ/libInit.a" "$OBJ"/*.o
fi
cd "$HERE"
~/.elan/toolchains/leanprover--lean4---v4.34.0/bin/lean -c ThreadLab.c ThreadLab.lean
for f in ThreadLab lab_ffi lab_shim; do emcc $CG $INC -c $f.c -o "$OUT/$f.o"; done
LINK="-sMALLOC=${MALLOC:-dlmalloc} -sALLOW_MEMORY_GROWTH=1 -sINITIAL_MEMORY=67108864 -sMAXIMUM_MEMORY=4294967296 -sSTACK_SIZE=1048576 \
  -sMODULARIZE=1 -sEXPORT_NAME=ThreadLab -sENVIRONMENT=web,worker,node \
  -sEXPORTED_FUNCTIONS=_lab_boot,_lab_run,_lab_ring,_lab_mixed,_lab_bg,_lab_bg_naive,_lab_region_js,_malloc,_free \
  -sEXPORTED_RUNTIME_METHODS=HEAPU8,wasmMemory"
[ "$V" = mt ] && LINK="$LINK -sPTHREAD_POOL_SIZE=${POOL:-4} -sDEFAULT_PTHREAD_STACK_SIZE=8388608"
emcc $CG "$OUT/ThreadLab.o" "$OUT/lab_ffi.o" "$OUT/lab_shim.o" "$OBJ/libInit.a" "$RT/lib/lean/libleanrt.a" "$RT/libuv/src/libuv/libuv.a" \
  $LINK -o "$OUT/threadlab.js"
ls -la "$OUT"/threadlab.*
node -e '
const fs=require("fs"),z=require("zlib"),d=process.argv[1];
for (const f of fs.readdirSync(d).filter(f=>/^threadlab\.(js|wasm)$/.test(f))) { const b=fs.readFileSync(d+"/"+f); console.log(f.padEnd(16), "raw", String(b.length).padStart(9), "brotli", String(z.brotliCompressSync(b,{params:{[z.constants.BROTLI_PARAM_QUALITY]:11}}).length).padStart(8)); }' "$OUT"
